        category: .whiteCollar,
        headlines: ["Rideshare Driver Used Passenger's Forgotten Card for Food Orders and a Gift Card", "Delivery Address Matches Driver's Apartment"],
        law: "cardFraud",
        threshold: 5,
        spec: "Used a credit card belonging to {V}, a card issued in another person's name, to obtain $176 in goods and services, without consent, on {DATE}.",
        ages: 19...55,
        victim: true,
        summary: "{V} left a credit card on the back seat of a rideshare on {DATE}. Over the next day the card was used three times: for a $41 food delivery order, a $90 pharmacy order and a $45 gift card. Every order was delivered to {D}'s apartment, and {D} had driven {V}. The rideshare trip record listed {D}. {DL} says {D.he} found the card and meant to return it after eating.",
        state: [E(.document, 3, "Rideshare Trip Record", "{D} drove {V} the night before."), E(.digital, 3, "Delivery Records", "All three orders went to {D}'s apartment."), E(.document, 2, "Card Statement", "$176 in charges in a day."), E(.video, 1, "Pharmacy Camera", "{D} collects a pharmacy order.")],
        defense: [E(.statement, 1, "Meant to Return", "{DL} says {D.he} meant to return the card."), E(.statement, 1, "Found It", "{DL} says it was on the seat.")],
        role: "Cardholder",
        exam: [.direct("What did you leave behind in the rideshare on {DATE}?", "\"A credit card. It slipped out of my coat pocket onto the back seat when I got out, and I did not realize it was gone until the next day.\""), .direct("Who was driving the rideshare that night?", "\"{D}. The trip record in the app lists {DL} as the driver, with the pickup, the route and the drop-off time all recorded.\""), .direct("What charges showed up on the card the following day?", "\"A $41 food delivery, a $90 pharmacy order and a $45 gift card. Together they came to $176, and I had made none of them.\""), .direct("Where were the three orders delivered?", "\"All three went to the same apartment. When I asked the card company for the delivery address, it matched the address on {DL}'s driver profile.\""), .direct("What did you do when you saw the charges?", "\"I froze the card and called the bank. I filed a dispute for the $176 and then went through the app to see who had driven me that night.\""), .direct("Did the card come back to you?", "\"No. Nobody called, nobody sent it, and the app showed no message about a lost item until after the orders had already been delivered.\""), .cross("You did not contact {D} before the orders were placed, did you?", "\"No. I did not know the card was missing until the next day. I never had the chance to ask {D.him} about it before the orders.\""), .cross("Cards fall out of pockets in cars all the time, don't they?", "\"They do. That is how I lost it. I had no reason to think a driver would find it and treat it as free money.\""), .cross("{D} left a note in the app after the orders, didn't {D.he}?", "\"A message did come through later, saying the card had been found. It arrived after the orders had been delivered and the charges had posted.\""), .cross("The charges were small, weren't they?", "\"Each charge was under $100, and the total was $176. It is not a big sum, but it is still money I did not agree to spend.\""), .cross("You cannot say what {D} planned to do with the card, can you?", "\"Only what {D.he} did with it. I cannot see {D.his} mind, but the card was used three times in one day, and that is not what returning a card looks like.\"")],
        theory: ("{D} used a passenger's forgotten card.", "A driver who meant to return it."),
        allocution: "\"It was wrong from the start, and I knew it.\"",
        truths: ("{DL} used the card before ever contacting {V}.", "{DL} used the app message system to leave a note after the orders."),
        defendant: [.direct("Did you use the card you found in your back seat?", "\"Yes, I did. I found it the next morning when I cleaned out my car, and I used it that day to order food. I should not have.\""), .direct("How did you find the card?", "\"I was vacuuming the back seat after a long shift and saw it wedged between the cushions. I recognized the name from my passenger list.\""), .direct("Why did you decide to order with it?", "\"I had been driving late and I was hungry. I told myself I would pay it back or return it right after, and I know how weak that sounds.\""), .direct("Why did you place a second and third order?", "\"I kept telling myself it was only a little more. The pharmacy order was for a prescription I had been putting off, and the gift card was for a family member.\""), .direct("What did you do after the orders were delivered?", "\"I felt sick about it. I sent a message through the app saying I had found the card, and I wrote that I would return it.\""), .direct("Do you still have the card?", "\"I kept it in my glove box until the deputy asked for it. I handed it over right away and told the deputy everything I had done.\""), .cross("You used the card before you ever contacted {V}, didn't you?", "\"Yes, I did. I used it first and wrote to the passenger afterward. I know the order was wrong.\""), .cross("You ordered three times in a day, didn't you?", "\"Yes. It was three orders, not one. Each time I told myself it was the last, and it was not.\""), .cross("The orders all went to your own apartment, didn't they?", "\"Yes. I had them sent to my apartment because it was the only address I use. I did not try to hide anything.\""), .cross("You are a rideshare driver and you know passengers lose things, don't you?", "\"Yes. The app tells drivers to message the passenger and return lost items. I did not follow that, and I should have.\""), .cross("If you meant to return it, why not message {V} first?", "\"Because I was embarrassed and hungry, and I made a poor choice. I wish I had messaged first, and I did not.\"")],
        openings: ("A passenger left a credit card on the back seat of a rideshare, and within a day it was used three times for orders delivered to the driver's apartment. The records will show it.", "{D} found a forgotten card, made a mistake, and meant to return it. This is not a story about a thief. It is about one bad decision and an honest message afterward."),
        closings: ("The trip record, the three deliveries, and the $176 in charges all point to {D}. The card was used first and the message came after, and that order tells you the intent.", "{D} found a card, used it out of weakness, felt ashamed, and wrote to the passenger. A bad decision is not the same as a plan to steal."),
        timeline: [(-1, "{V} leaves the card."), (0, "The first order."), (0, "The second order."), (0, "The gift card."), (1, "{V} reports the charges.")],
        identified: "A rideshare trip record.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let homeInvasionBurglaryV1 = SmallCases.make(
        key: "story.homeInvasionBurglary",
        category: .property,
        headlines: ["Sliding Door Slides Open at 3 A.M., Family Wakes to Car Keys Missing and Sedan Gone From Driveway", "Dog's Barking Doesn't Wake Residents in Time"],
        law: "burglary1",
        threshold: 7,
        spec: "Broke and entered the occupied dwelling of {V} at night with intent to commit larceny therein, on {DATE}.",
        ages: 20...45,
        victim: true,
        summary: "{V} and family slept upstairs on {DATE} while a person slipped through an unlocked sliding door at about 3 a.m., took a purse, two sets of car keys and a laptop from the kitchen, and drove away in the family's sedan. A neighbor's camera showed the sedan leaving. Two days later a deputy found the sedan in {D}'s possession with the laptop in the back seat. {DL} says {D.he} bought the sedan from a seller for $1,500 cash.",
        state: [E(.physical, 3, "Laptop", "In the sedan's back seat, with {V}'s name."), E(.video, 3, "Neighbor Camera", "The sedan leaves at 3:12 a.m."), E(.document, 2, "Title and Plates", "The sedan is {V}'s."), E(.forensic, 1, "Shoe Print", "A print on the kitchen floor.")],
        defense: [E(.statement, 1, "Bought the Sedan", "{DL} says {D.he} paid $1,500 for the sedan."), E(.document, 1, "Cash Withdrawal", "A $1,500 withdrawal the day before.")],
        role: "Sheriff's detective",
        exam: [.direct("How did the sedan come to your attention?", "\"A deputy spotted the family's stolen sedan two days after the break-in. {D} was in possession of it, and the plates did not match the vehicle.\""), .direct("What did you find inside the sedan?", "\"A laptop in the back seat with {V}'s name on a sticker. It had been taken from the kitchen counter the night of the break-in.\""), .direct("What did the neighbor's camera show?", "\"The family's sedan pulling out of the driveway at 3:12 in the morning and heading down the street. It did not show who was driving.\""), .direct("How did the intruder get into the house?", "\"Through an unlocked sliding door at about three in the morning. A person took a purse, two sets of car keys, and a laptop from the kitchen.\""), .direct("What did you find on the kitchen floor?", "\"A shoe print in dust near the sliding door. We photographed it and compared it with the shoes {DL} was wearing when the sedan was found.\""), .direct("What did {D} tell you about the sedan?", "\"{D.He} said {D.he} bought it from a seller for $1,500 in cash. {D.he} could not give a name, an address or a phone number for that seller.\""), .cross("No one saw the defendant inside the house, did they?", "\"No. No witness places {DL} in the house. The family was asleep upstairs and did not hear anyone.\""), .cross("The shoe print was not a match to the defendant's shoes, was it?", "\"The comparison was inconclusive. The print was partial, and I cannot say it was made by {D.his} shoes.\""), .cross("{D} withdrew $1,500 the day before, which is consistent with buying a car, isn't it?", "\"It is consistent with that. The bank record shows a $1,500 withdrawal on the day before the break-in.\""), .cross("The title was never signed over to the defendant, correct?", "\"Correct. There was no signed title and no bill of sale. {D.He} had the keys and a car, but no paper showing a sale.\""), .cross("The laptop was in the back seat in plain view, wasn't it?", "\"Yes, in the back seat and not hidden. I cannot say whether {D.he} knew it was there or put it there.\"")],
        theory: ("{D} drove away in a car taken during a night break-in.", "A buyer of a bargain sedan."),
        allocution: "\"I wasn't thinking about the person on the other end. I am now.\"",
        truths: ("{DL} could not name or describe the seller.", "{DL} had changed the plates."),
        defendant: [.direct("Did you break into {V}'s home?", "\"No. I have never been inside that house. I was home that night, and I did not know the family or where they lived.\""), .direct("How did you come to have the sedan?", "\"I bought it from a seller who met me in a parking lot. The seller had keys and a car at a price that looked fair, and I paid $1,500 in cash.\""), .direct("Why did you pay in cash?", "\"The seller wanted cash and would not take a check. I took out $1,500 the day before from my own account for exactly that reason.\""), .direct("Why did you change the plates?", "\"I put on plates I already had because the car came with none, and I did not have time to register it. That was careless of me.\""), .direct("What did you do when you found the laptop in the back seat?", "\"I thought it had been left by the previous owner. I did not think about it right away, and I meant to ask the seller about it.\""), .direct("What did you do when the deputy stopped you?", "\"I told the deputy I had bought the car and showed the cash withdrawal. I did not run, and I did not try to hide the laptop.\""), .cross("You cannot name the seller, can you?", "\"No. I only had a first name and a phone number that did not work later. I should have asked for more, and I did not.\""), .cross("You changed the plates on a car you had just bought, didn't you?", "\"Yes. I changed them. I should have registered it first, and I understand now why that looks like I knew something was wrong.\""), .cross("A sedan with a laptop in the back seat and no title looks like trouble, doesn't it?", "\"It does now. At the time I was excited about the deal and I did not think about what could be wrong with it.\""), .cross("You did not get a bill of sale, did you?", "\"No. I did not get anything in writing. It was a handshake and cash, and I regret not asking for more.\""), .cross("You could have called the sheriff's office when you found the laptop, couldn't you?", "\"Yes, I could have. I did not, and I should have called as soon as I saw the name on it.\"")],
        openings: ("A family slept upstairs while someone slid through an unlocked door, took a laptop and keys, and drove away in the family's sedan. Two days later {D} had the car.", "{D} bought a bargain sedan from a stranger, paid cash, and did not know it was stolen. That is a mistake, and being careless is not the same as being a burglar."),
        closings: ("The sedan was stolen at 3:12 a.m., the laptop was in the back seat, and {D} had changed the plates. {D} cannot name the seller or show a sale.", "No one saw {D} in the house, and the shoe print does not match. {D} paid $1,500 and was cooperative. A bad purchase is not a burglary."),
        timeline: [(0, "3:05 a.m.: the intruder enters."), (0, "3:12 a.m.: the sedan leaves."), (0, "6 a.m.: {V} finds the keys missing."), (2, "A deputy finds the sedan."), (2, "The laptop is recovered.")],
        identified: "A neighbor's camera.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let puppyMillCratesV1 = SmallCases.make(
        key: "story.puppyMillCrates",
