        timeline: [(-540, "The loan."), (-300, "The first card."), (0, "The bank flags the account."), (20, "The investigator calls.")],
        identified: "A loan application.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof", "eyewitnessID", "expertTestimony"],
        genders: ["D": .male, "V": .male, "ALT": .female])

