        exam: [.direct("What did {V} find when {V} came home at 5 p.m.?", "\"The front door had been pried open, and a laptop and a jewelry case were missing from the bedroom. Drawers were pulled open, and the frame was splintered.\""), .direct("What did the neighbor's camera show?", "\"It shows {D} walking away from {V}'s house in the early afternoon, carrying a bag. The video is clear enough to show clothing and a build, and a face turned toward the street.\""), .direct("What was pawned that afternoon?", "\"A ring that matched one in the missing jewelry case. A pawn shop took it in from {DL} within hours of the time shown on the camera.\""), .direct("What did you find about the pry marks on the door?", "\"They fit a pry tool found in {DL}'s car. The width of the blade and the shape of the tip were consistent with the marks on the frame.\""), .direct("What did {D} say about the ring?", "\"That {DL} bought it from a friend. {DL} could not give the friend's full name and did not have a receipt or any message about the sale.\""), .direct("What did you do to check the story about the friend?", "\"I asked for a name and a number. {D.He} gave a first name only, and the number belonged to a phone that was not in service.\""), .cross("No bag was found in the defendant's possession, was it?", "\"No bag was recovered. I cannot tell you what was in it from the video, and I did not find the laptop.\""), .cross("The friend the defendant named may exist, mightn't they?", "\"The friend may exist. I could not locate anyone matching the name and description, and {DL} could not help me find that person.\""), .cross("The pry tool is a common type, isn't it?", "\"Yes. It is sold in most hardware stores. I can say it fits the marks, and I cannot say it is the only tool that would.\""), .cross("The ring was sold at a pawn shop, which keeps records, doesn't it?", "\"Yes. The pawn shop took ID and a photograph. {D.He} did not use a false name, and I give that some weight.\""), .cross("You did not see the defendant enter the house, did you?", "\"No. The camera shows {DL} walking away. It does not show the door, and I cannot say who opened it.\"")],
        theory: ("{D} broke into a house at midday.", "A ring bought from a friend."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} had no receipt for the ring.", "{DL} pawned the ring within hours."),
        defendant: [.direct("Did you break into {V}'s house?", "\"No. I walked past that house on my way to a friend's. I never went inside, and I did not touch the door.\""), .direct("What was in the bag you were carrying?", "\"Clothes and a few things I was returning. It was an ordinary bag, and nothing in it came from that house.\""), .direct("How did you get the ring you took to the pawn shop?", "\"I bought it from a friend a few days earlier. It looked like a nice ring, and I thought I could get a fair price for it.\""), .direct("Why did you pawn it that day?", "\"I needed money for rent and groceries. I took it in right away, and I used my own ID because I thought the ring was mine to sell.\""), .direct("Why was a pry tool in your car?", "\"I do odd jobs, and I carry tools in my trunk. It is a common tool, and I use it for work every week.\""), .direct("What did you do when the detective came to talk to you?", "\"I told the detective everything I could, including the friend's first name. I did not run, and I let the detective search my car.\""), .cross("You do not have a receipt for the ring, do you?", "\"No. It was a cash deal with a friend. I did not think I would need proof, and now I wish I had asked.\""), .cross("You pawned it within hours of being near the house, didn't you?", "\"Yes. It looks bad, and I understand that. I was not at the house for any reason other than walking.\""), .cross("You cannot give the friend's full name, can you?", "\"I have only a first name and a number that does not work. I know it makes my story hard to believe.\""), .cross("The pry marks fit the tool in your car, don't they?", "\"They could. The tool is common, and I have used it on many jobs, but I did not use it on that door.\""), .cross("You were seen walking away from the house with a bag, weren't you?", "\"Yes. I was walking by and it was a normal bag. I do not know why anyone would think it came from that house.\"")],
        openings: ("{V} came home at 5 p.m. to find the door pried open and a laptop and jewelry gone. A neighbor's camera showed {D} walking away with a bag, and {D} pawned a matching ring hours later.", "{D} walked past the house and bought a ring from a friend. {D} pawned it with real ID, in a real shop, and did not hide anything."),
        closings: ("The camera, the pawn ticket, and the pry tool fit {D}. A ring pawned within hours and no receipt for the purchase.", "No one saw {D} enter the house, no bag was found, and {D} used a real ID at the pawn shop. A bag and a ring are not proof of a burglary."),
        timeline: [(0, "11 a.m.: the break-in."), (0, "2 p.m.: the pawn."), (0, "5 p.m.: {V} returns."), (2, "The ticket is found.")],
