        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let witnessPaidToLeaveV1 = SmallCases.make(
        key: "story.witnessPaidToLeave",
        category: .violent,
        headlines: ["Cash Transfer Sent to Trial Witness With Message: 'Take a Trip'", "Phone Records Tie Sender to Defendant's Circle"],
        law: "witnessIntimidation",
        threshold: 7,
        spec: "Attempted to deter a witness from testifying by offering a thing of value, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Three days before a trial, {V}, a witness, received $800 through a payment app from {D} with a message: 'take a trip, a gift.' {V} reported it. {DL} says {D.he} was repaying an old debt.",
        state: [E(.digital, 3, "Payment Record", "$800 sent by {D} to {V}."), E(.digital, 3, "Message", "'Take a trip, a gift.'"), E(.document, 2, "Trial Calendar", "Trial set three days later.")],
        defense: [E(.statement, 2, "Old Debt", "{DL} says {D.he} owed {V} money.")],
        role: "Witness",
        exam: [.direct("What did you receive on your phone three days before the trial?", "\"An $800 payment through a payment app from {D}, with a message that said 'take a trip, a gift.' I had not asked for any money from {D.him}.\""), .direct("Who is {D} to you?", "\"{DL} is the defendant in the case where I am a witness. I had seen {DL} at the incident, and I was set to testify at the trial.\""), .direct("Why did you find the message troubling?", "\"It arrived three days before I was due to testify. A gift to take a trip right then sounded like an offer to be out of town on the trial date.\""), .direct("What did you do after you got the payment?", "\"I did not spend it. I took screenshots and told the prosecutor. I also gave the investigators access to my phone and the payment record.\""), .direct("How did you feel receiving it?", "\"Uneasy and a little scared. I did not know what {D.he} expected from me, and I did not want to be part of anything improper.\""), .direct("Did you owe {D} anything or {D} owe you?", "\"No. I had no financial dealings with {D.him} before that payment. I never lent money and never borrowed any from {D.him}.\""), .cross("{D} says it was repayment of an old debt, doesn't {D.he}?", "\"That is what I understand. I do not recall any debt. I may have given {DL} a few dollars a long time ago, but nothing close to $800.\""), .cross("You and the defendant knew each other before the incident, didn't you?", "\"We knew each other casually. I would not say we were friends, and we had never exchanged money.\""), .cross("The message does not mention the trial, does it?", "\"No. It says to take a trip and calls it a gift. It does not say anything about the trial.\""), .cross("You kept the payment and did not return it, did you?", "\"I did not send it back because I was told to preserve it as evidence. It is still in my account.\""), .cross("You cannot say what the defendant meant by the message, can you?", "\"No. I can only say how it read to me. I took it as an offer to leave town, and I may be wrong.\"")],
        theory: ("{D} paid a witness to leave town.", "A debt repaid."),
        allocution: "\"I should have walked away.\"",
        truths: ("{DL} knew the trial date.", "{DL} had never repaid anything before."),
        defendant: [.direct("Did you send $800 to {V} to keep {V} from testifying?", "\"No. I sent it because I owed {V} money from a long time ago. I wanted to settle up before something happened to me.\""), .direct("What was the old debt?", "\"A loan from years ago, when I was short on rent. It was never written down. I remember it being around $800 over time.\""), .direct("Why did you write 'take a trip, a gift'?", "\"It was a joke. I thought {V} might like a vacation, and I wrote it in a light tone. I did not think about the trial when I typed it.\""), .direct("Why did you send it three days before the trial?", "\"I got a tax refund that week and had the money. The timing was a coincidence, and I did not think about how it would look.\""), .direct("Did you ever ask {V} not to testify?", "\"No. I never asked {V} to stay away or to change what {V} would say. I did not contact {V} about the case at all.\""), .direct("What would you say to {V} now?", "\"That I am sorry for the confusion. I should have sent a plain note that said I was paying a debt, and not a joke.\""), .cross("You knew the trial date was three days away, didn't you?", "\"Yes. I knew the date, and I understand why it looks like I was trying to influence {V}. That was not my purpose.\""), .cross("You had never repaid anything to {V} before, had you?", "\"No. I put it off for years. That makes it look odd that I paid right before the trial.\""), .cross("You called it a gift in the message, didn't you?", "\"I did. That was a mistake. It does not read like a debt, and I should have used a clearer word.\""), .cross("You have no record of the old debt, do you?", "\"No. It was a handshake loan. I know I cannot prove it, and I regret that.\""), .cross("You could have waited until after the trial to pay, couldn't you?", "\"I could have. I treated the date as unimportant. I now understand that the timing was a terrible choice.\"")],
        openings: ("Three days before a trial, a witness received $800 through a payment app from the defendant, with a message that said 'take a trip, a gift.' The witness reported it right away.", "{D} was repaying an old debt and wrote a clumsy joke. The timing was bad, but {D} never asked {V} to stay away or change a word."),
        closings: ("$800, three days before the trial, with a message that said to take a trip. The timing and the wording tell you what {D} wanted.", "{D} had an old debt, a tax refund, and a bad sense of humor. A confusing message sent at a bad time is not witness tampering."),
        timeline: [(-3, "The trial date is set."), (0, "The payment."), (0, "{V} reports it."), (1, "Detectives get the records.")],
        identified: "A payment record.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let counterfeitTicketsV1 = SmallCases.make(
        key: "story.counterfeitTickets",
        category: .whiteCollar,
        headlines: ["Stadium Scanner Flags Duplicate Barcodes; Buyers Share One Seller", "Screenshots Sold as Tickets to Six Fans"],
        law: "falsePretenses",
        threshold: 7,
        spec: "Obtained $1,840 from six buyers, including {V}, by selling counterfeit tickets to a college football game, on or about {DATE}.",
        ages: 19...30,
        victim: true,
        summary: "Six buyers paid {D} through a payment app for tickets to a sold-out game. At the gate, scanners showed the barcodes had already been used. The tickets were screenshots of real ones. {V} was one of the buyers. {DL} says {D.he} resold tickets in good faith.",
        state: [E(.digital, 3, "Payment Records", "Six payments to {D}."), E(.digital, 3, "Screenshots", "Duplicate barcodes."), E(.document, 2, "Stadium Report", "Barcodes scanned earlier.")],
        defense: [E(.statement, 2, "Good Faith", "{DL} says {D.he} resold tickets from another seller.")],
        role: "Ticket buyer",
        exam: [.direct("What did you buy from {D} and how did you pay?", "\"A ticket to a sold-out game, paid through a payment app. I sent the money before the game and received a screenshot of the ticket by message.\""), .direct("What happened when you got to the gate?", "\"The scanner rejected my barcode and showed it had already been used. A staff member told me that other people with the same barcode were turned away too.\""), .direct("How many buyers were affected?", "\"Six people sent money to {D} and had the same problem. We compared screenshots and found some of the barcodes were identical.\""), .direct("What did you learn from the stadium report?", "\"The barcodes had been scanned earlier by someone else. That means the tickets were copies of real ones, and only the first person to scan got in.\""), .direct("What did you do after the gate?", "\"I messaged {D.him} and asked for a refund. {D.He} did not reply, and soon after I found I had been blocked on the app.\""), .direct("How much did you pay, and what did you lose?", "\"I paid several hundred dollars. I also lost the day, because I had arranged a family outing around that game.\""), .cross("Screenshots of tickets are common in resale, aren't they?", "\"Yes. Many resale tickets are sent as screenshots. I did not know the same screenshot could be sold to more than one person.\""), .cross("You do not know where the defendant got the tickets, do you?", "\"No. {DL} told me they were from a season-ticket holder. I do not know whether that is true.\""), .cross("The tickets might have been real when the defendant bought them, mightn't they?", "\"It is possible. I know only that the barcodes were used before I got to the gate.\""), .cross("{D} did not promise a refund in writing, did {D.he}?", "\"No. The conversation was brief and about price. There was no written promise of a refund.\""), .cross("Blocking a number is something people do when they are upset, isn't it?", "\"Sometimes. But it also happens when someone does not want to answer. I cannot say why {D.he} did it.\"")],
        theory: ("{D} sold copies of tickets.", "A resale gone wrong."),
        allocution: "\"I should have told the truth the first time.\"",
        truths: ("{DL} sold the same barcode more than once.", "{DL} blocked buyers after the game."),
        defendant: [.direct("Did you sell copies of tickets to the six buyers?", "\"No. I sold tickets I thought were real. I bought them from another seller and resold them for a small profit.\""), .direct("Where did you get the tickets?", "\"From a seller online who said they were a season-ticket holder. I paid and received screenshots, and I passed them on to the buyers.\""), .direct("Why did you sell the same barcode to more than one person?", "\"I did not realize I had. The seller sent me several screenshots, and I thought each one was different. It was a mistake.\""), .direct("Why did you block the buyers after the game?", "\"People started sending angry messages and threats. I felt overwhelmed and blocked them. I should have answered and tried to make it right.\""), .direct("Have you tried to refund the buyers?", "\"I offered to refund the ones I could reach. Some accepted. I did not have enough to pay everyone at once.\""), .direct("What did you learn from this?", "\"That resale is risky. I should have checked the tickets with the stadium, and I should not have resold anything I could not verify.\""), .cross("You sold the same barcode more than once, didn't you?", "\"The records show that. I did not know. I looked at the screenshots and thought they were different tickets.\""), .cross("You blocked the buyers right after the game, didn't you?", "\"Yes. I did. I was scared and did not know what to do, and I know it made things worse.\""), .cross("You cannot name the seller you bought from, can you?", "\"I have a username that is now deleted. I did not take a photo of the person or any other record.\""), .cross("You took money from six people for tickets that did not work, didn't you?", "\"Yes. I did. I did not intend to cheat anyone, but the effect on them was real.\""), .cross("You never checked the barcodes before reselling, did you?", "\"No. I trusted the seller. I should have asked the stadium, and I understand that now.\"")],
        openings: ("Six buyers paid {D} for tickets to a sold-out game. At the gate, the scanners showed each barcode had already been used, because the tickets were screenshots of real ones.", "{D} resold tickets from another seller in good faith. {D} did not know the barcodes were copies, and a resale that goes wrong is not a scam."),
        closings: ("Six payments, six screenshots, duplicate barcodes, and a blocked buyer list. {D} sold the same ticket more than once and cut off everyone afterward.", "{D} bought from a seller online, resold in good faith, and offered refunds when {D} could. A bad resale is not the same as counterfeiting."),
        timeline: [(-7, "The listing."), (-1, "Payments arrive."), (0, "The gate."), (3, "Buyers report.")],
        identified: "Payment records.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof", "searchSeizure"])

    static let wheelBootCutV1 = SmallCases.make(
        key: "story.wheelBootCut",
        category: .property,
        headlines: ["Driver Frees Car From Parking Boot With Bolt Cutters, Leaves $450 Clamp in Pieces", "Tow Operator's Photos Show Sheared Steel"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a wheel immobilizer, causing damage of $450, on {DATE}.",
        ages: 20...60,
