    static let hailClaimV1 = SmallCases.make(
        key: "story.hailClaim",
        category: .whiteCollar,
        headlines: ["Adjuster's Photos Show Matching Dents Down Every Shingle Row", "Engineer: Storm Hail Doesn't Land in Straight Lines"],
        law: "insuranceFraud",
        threshold: 8,
        spec: "With intent to defraud, presented a claim to {D.his} homeowner's insurer for $23,600 for roof damage not caused by hail, on {DATE}.",
        ages: 30...62,
        victim: false,
        summary: "A hailstorm crossed the area on {DATE}. {D} filed a claim for $23,600 to replace the roof. An adjuster found dozens of round marks of identical size, many overlapping in straight rows. An engineer found hammer-shaped indentations. {DL} says the storm caused all of it.",
        state: [E(.forensic, 3, "Engineer Report", "Hammer marks, not hail."), E(.physical, 3, "Shingle Samples", "Identical impact patterns."), E(.document, 2, "Weather Data", "No hail over {D}'s block that day.")],
        defense: [E(.statement, 2, "Storm Damage", "{DL} says the storm caused the damage.")],
        role: "Forensic engineer",
        exam: [.direct("What did you find when you examined the roof shingles?", "\"Dozens of round indentations of nearly identical size, many in straight rows. Natural hail varies in size and falls in a random scatter, not in even lines.\""), .direct("What shape were the indentations?", "\"Hammer-shaped. Each one had a flat circular face with a crisp edge, which is how a hammer head strikes. Hailstones leave a different, softer, irregular dent.\""), .direct("What did the shingle samples show under magnification?", "\"Identical impact patterns, with the same depth and the same fractures in the granules. Hail damage shows variation from stone to stone, and these did not.\""), .direct("What did the weather data show for {D}'s block on that day?", "\"No hail. Radar and the nearest weather stations recorded no hail over that block, though hail fell in other parts of the area.\""), .direct("How large was the defendant's claim?", "\"$23,600 to replace the roof. {D} filed it within three days of the storm and asked for a full replacement.\""), .direct("How old was the roof?", "\"Well past twenty years. The shingles were brittle and worn, and the roof was already at the end of its expected life.\""), .cross("Neighbors on other streets did file valid hail claims, didn't they?", "\"Yes. There was hail in other parts of town, and many of those claims were valid. I looked at the ones nearest to {D.his} house for comparison.\""), .cross("An old roof is more fragile than a new one, isn't it?", "\"Yes, and that is true here. But age does not produce hammer-shaped marks in neat rows, and that is what I found.\""), .cross("You did not see anyone hammering the roof, did you?", "\"No. I reached my conclusion from the marks, the samples, and the weather data. I did not observe how the marks were made.\""), .cross("A storm can cause damage that looks odd, can't it?", "\"Yes, storms do strange things. But the shape, the spacing and the uniformity here are not typical of any storm I have studied.\""), .cross("Some marks on the roof could have come from hail, couldn't they?", "\"Possibly a few. Most of the marks were consistent with a hammer, and I cannot rule out a small amount of hail on a nearby roof.\"")],
        theory: ("{D} hammered a roof to collect on hail.", "A storm and an old roof."),
        allocution: "\"I took advantage of someone who trusted me, and I'm sorry.\"",
        truths: ("{DL} had been told the roof was too old to cover.", "{DL} filed a claim within three days."),
        defendant: [.direct("Did you hammer your roof to make a claim?", "\"No. I did not touch the shingles. A hailstorm came through and I saw damage afterward, and I called my insurance company.\""), .direct("What did you see on your roof after the storm?", "\"Round marks across the shingles. I thought they looked like hail damage. I took photos from the ground and from a ladder.\""), .direct("Why did you file the claim so quickly?", "\"I wanted to get it done before the weather turned again. A neighbor said the insurance company was busy, and I did not want to wait.\""), .direct("Were you told your roof was too old to be covered?", "\"No. Nobody told me that. I believed I was covered for storm damage, and I paid my premiums on time.\""), .direct("How did you feel when the engineer's report came back?", "\"Shocked. I could not believe anyone would think I hammered my roof. I told them what I saw and I asked them to check again.\""), .direct("What would you like the insurance company to understand?", "\"That I did not damage my own roof. I filed a claim for what I believed was storm damage, and I did nothing wrong.\""), .cross("You filed the claim within three days, didn't you?", "\"Yes. It seemed like the right thing to do. I did not think it was too fast.\""), .cross("The weather data shows no hail over your block, doesn't it?", "\"That is what they say. It hailed nearby, and I did not know it missed my street. I saw marks and assumed.\""), .cross("Your roof was past twenty years old, wasn't it?", "\"Yes. It was old, and I knew it needed replacing. I was hoping the insurance would help.\""), .cross("You asked for a full replacement, didn't you?", "\"Yes. The adjuster said the damage looked bad, and I thought that was a fair request.\""), .cross("The marks on your roof are in straight rows, aren't they?", "\"I did not notice that at the time. I am not an expert, and I trusted that the marks were from the storm.\"")],
        openings: ("After a hailstorm, {D} filed a $23,600 claim for a new roof. An engineer found hammer-shaped marks in straight rows, and weather data showed no hail over {D}'s block.", "{D} saw damage after a storm and filed an honest claim. The roof was old and the marks were real, and {D} never hammered anything."),
        closings: ("Hammer marks in neat rows, identical impact patterns, no hail on the block, and a claim filed in three days. The roof was damaged by a person.", "{D} saw damage after a storm and reported it. An old roof and a puzzling pattern are not proof that {D} hammered it."),
        timeline: [(-30, "A denial for the old roof."), (0, "The storm."), (3, "The claim."), (14, "The engineer inspects.")],
        identified: "An engineer's report.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof", "expertTestimony"])

